<template>
  <div class="rules-page">
    <header class="header"><div><strong>白同学短剧助手</strong><span>视频提示词规则包</span></div><el-button @click="router.back()">返回</el-button></header>
    <main>
      <section class="hero"><div><p class="eyebrow">VIDEO PROMPT SKILL</p><h1>提示词规则包</h1><p>把你习惯的提示词 Skill 安装为项目可选规则。导入不会覆盖旧版本，也不会改写已经保存的提示词。</p></div><label class="upload"><input type="file" accept=".zip,.json,.md" @change="importFile" :disabled="busy" /><span>{{ busy ? '正在导入…' : '导入 ZIP / JSON / SKILL.md' }}</span></label></section>
      <section class="grid"><article v-for="pack in packs" :key="pack.id" class="pack" :class="{active: settings.pack_id === pack.id}"><div class="pack-top"><div><h2>{{ pack.name }}</h2><small>v{{ pack.version }} · {{ pack.active_paths?.length || 0 }} 个生效文件</small></div><el-tag v-if="settings.pack_id === pack.id" type="success">当前项目使用</el-tag></div><p>{{ pack.source }}</p><div class="files">{{ (pack.active_paths || []).slice(0, 4).join(' · ') }}</div><div class="actions"><el-button size="small" @click="choose(pack)">{{ settings.pack_id === pack.id ? '已选择' : '用于本项目' }}</el-button><el-button size="small" plain @click="edit(pack)">编辑规则</el-button><a :href="videoPromptRulesAPI.exportUrl(pack.id)" download>导出 JSON</a></div></article><div v-if="!packs.length" class="empty">还没有规则包，请导入你的 SKILL.md 或 ZIP。</div></section>
      <section class="settings"><div><h2>当前项目流程</h2><p>{{ settings.name }} {{ settings.version ? `v${settings.version}` : '' }}</p></div><div class="switches"><label><el-switch v-model="settings.auto_polish" @change="saveSettings" /> 自动润色</label><label><el-switch v-model="settings.append_style" @change="saveSettings" /> 提交时追加项目风格</label></div><p class="note">启用自定义 Skill 后，平台会按其规则编译全能提示词，并移除旧的“每段至少两步运镜、强制换措辞”等附加要求。提交前仍需检查参考图编号、时间轴和素材绑定。</p></section>
      <el-dialog v-model="editor.open" title="编辑规则包（保存为新版本）" width="min(900px, 92vw)"><p class="editor-hint">只编辑 SKILL.md 的正文；原版本不可变，保存后会生成新的规则包版本。</p><el-input v-model="editor.content" type="textarea" :rows="20" /><template #footer><el-button @click="editor.open=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveEdited">保存新版本</el-button></template></el-dialog>
    </main>
  </div>
</template>
<script setup>
import { ref, onMounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { videoPromptRulesAPI } from '@/api/videoPromptRules'
const router = useRouter(); const route = useRoute(); const packs = ref([]); const busy = ref(false); const settings = ref({ pack_id: null, name: '平台内置规则', version: '', auto_polish: true, append_style: true }); const editor = ref({ open: false, pack: null, content: '' })
async function load() { const d = await videoPromptRulesAPI.list(); packs.value = d?.packs || []; if (route.params.id) settings.value = await videoPromptRulesAPI.getProject(route.params.id) }
async function importFile(e) { const file = e.target.files?.[0]; if (!file) return; busy.value = true; try { const bytes = await file.arrayBuffer(); let binary = ''; const data = new Uint8Array(bytes); for (let i = 0; i < data.length; i += 0x8000) binary += String.fromCharCode(...data.subarray(i, i + 0x8000)); const out = await videoPromptRulesAPI.importBase64(file.name, btoa(binary)); ElMessage.success(`已导入 ${out.pack.name} v${out.pack.version}`); await load() } catch (e) { ElMessage.error(e.message || '导入失败') } finally { busy.value = false; e.target.value = '' } }
async function choose(pack) { if (!route.params.id) return ElMessage.warning('请从具体项目进入规则设置'); settings.value = await videoPromptRulesAPI.setProject(route.params.id, { pack_id: pack.id, auto_polish: !!settings.value.auto_polish, append_style: !!settings.value.append_style }); ElMessage.success('已切换规则包') }
async function saveSettings() { if (!route.params.id || !settings.value.pack_id) return; settings.value = await videoPromptRulesAPI.setProject(route.params.id, { pack_id: settings.value.pack_id, auto_polish: !!settings.value.auto_polish, append_style: !!settings.value.append_style }) }
function edit(pack) { const skill = (pack.files || []).find(f => /(^|\/)SKILL\.md$/i.test(f.path)); editor.value = { open: true, pack, content: skill?.content || '' } }
async function saveEdited() { if (!editor.value.pack || !editor.value.content.trim()) return ElMessage.warning('SKILL.md 不能为空'); busy.value = true; try { const p = editor.value.pack; const files = (p.files || []).map(f => /(^|\/)SKILL\.md$/i.test(f.path) ? { ...f, content: editor.value.content } : { path: f.path, content: f.content }); const out = await videoPromptRulesAPI.importFiles({ name: p.name, version: `${p.version}-custom`, files, source: `基于 ${p.name} v${p.version} 编辑` }); editor.value.open = false; ElMessage.success(`已保存 ${out.pack.name} v${out.pack.version}`); await load() } catch (e) { ElMessage.error(e.message || '保存失败') } finally { busy.value = false } }
onMounted(load)
</script>
<style scoped>
.rules-page{min-height:100vh;background:#0c0d12;color:#eef0f5}.header{height:70px;padding:0 6vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #262936;background:#11131b}.header div{display:flex;gap:18px;align-items:baseline}.header strong{font-size:19px}.header span{color:#9da3b7}.header :deep(.el-button){background:#1c2030;border-color:#343a50;color:#e7e9f2}main{max-width:1180px;margin:0 auto;padding:54px 28px}.hero{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:34px}.eyebrow{color:#9d7cff;letter-spacing:.16em;font-size:12px}.hero h1{font-size:38px;margin:8px 0}.hero p{color:#aeb4c4;max-width:670px;line-height:1.7}.upload{display:inline-flex;align-items:center;padding:14px 20px;border:1px solid #7455e8;background:#6745dd;color:white;border-radius:9px;cursor:pointer}.upload input{display:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}.pack,.settings{border:1px solid #272c3d;background:#151823;border-radius:12px;padding:20px}.pack.active{border-color:#765cff;box-shadow:0 0 0 1px #765cff44}.pack-top{display:flex;justify-content:space-between;gap:12px}.pack h2,.settings h2{margin:0 0 8px;font-size:18px}.pack small,.pack p,.note{color:#9da3b7}.files{font:12px ui-monospace;color:#c1a9ff;min-height:38px;margin:18px 0}.actions{display:flex;gap:18px;align-items:center}.actions a{color:#bdaaff;text-decoration:none}.empty{padding:34px;color:#858ca0}.settings{margin-top:22px;display:flex;align-items:start;justify-content:space-between;gap:30px}.switches{display:flex;gap:22px;flex-wrap:wrap}.switches label{display:flex;align-items:center;gap:9px;color:#dfe2ea}.note{margin:18px 0 0;line-height:1.7;flex-basis:100%}@media(max-width:700px){.hero,.settings{display:block}.upload{margin-top:16px}.switches{margin-top:20px}}
</style>
